from typing import Dict, List, Sequence

def poly_eval(coeffs: Sequence[int], x: int, p: int) -> int:
    acc = 0
    for c in reversed(coeffs):
        acc = (acc * x + c) % p
    return acc

def shamir_share(secret: int, threshold: int, xs: Sequence[int], p: int,
                 randomness: Sequence[int]) -> Dict[int, int]:
    """Deal (t, n) Shamir shares: f(X) = secret + sum_k randomness[k-1] X^k."""
    assert len(randomness) == threshold - 1
    coeffs: List[int] = [secret % p] + [r % p for r in randomness]
    return {x: poly_eval(coeffs, x, p) for x in xs}

from typing import Dict, Sequence, Tuple

def inv_mod(a: int, p: int) -> int:
    return pow(a % p, p - 2, p)

def lagrange_interpolate_at(points: Sequence[Tuple[int, int]], x0: int, p: int) -> int:
    total = 0
    for i, (xi, yi) in enumerate(points):
        num, den = 1, 1
        for j, (xj, _) in enumerate(points):
            if i == j:
                continue
            num = (num * (x0 - xj)) % p
            den = (den * (xi - xj)) % p
        total = (total + yi * num * inv_mod(den, p)) % p
    return total

def shamir_reconstruct(shares: Dict[int, int], p: int) -> int:
    """Recover the secret f(0) from any t shares via Lagrange interpolation."""
    return lagrange_interpolate_at(list(shares.items()), 0, p)
